solver_code = """# sat_full.py — Solver core (Iterator)
# LEAN-compliant skeleton implementing the API:
#   init(cnf_meta, limits, policies) -> {ok, err?}
#   run(conflict_budget, time_ms) -> {status, model?}
#   add_learnt(clause) -> {ok, clause_id?, err?}
#   snapshot() -> Stats dict
#   reset_stats() -> {ok}
#
# Notes:
# - This is a skeleton. Propagation, conflict analysis, learning, and restarts
#   are left as TODOs but the structure, types, and invariants are in place.

from dataclasses import dataclass, field
from typing import List, Dict, Optional, Tuple, Any
import time

# ---------- Data Schemas ----------

@dataclass
class CnfMeta:
    n_vars: int
    clauses: List[List[int]]

@dataclass
class Limits:
    conflict_budget: int
    time_ms: int

@dataclass
class EncodingPolicies:
    atmost1_policy: str = "pairwise"
    cardinality_policy: str = "sequential"

@dataclass
class Stats:
    n_conflicts: int = 0
    n_propagations: int = 0
    n_decisions: int = 0
    n_restarts: int = 0
    learnt_count: int = 0
    avg_lbd: float = 0.0
    max_dl: int = 0
    trail_len_max: int = 0
    time_ms: int = 0
    n_vars_original: int = 0
    n_vars_aux: int = 0
    n_clauses_original: int = 0
    n_clauses_learnt: int = 0
    n_clauses_total: int = 0
    encoding_policy_atmost1: str = "pairwise"
    encoding_policy_cardinality: str = "sequential"
    restart_policy: str = "Luby"

# Error codes
E_BAD_INPUT = "E_BAD_INPUT"
E_LIMITS   = "E_LIMITS"
E_STATE    = "E_STATE"
E_NOMEM    = "E_NOMEM"

class Solver:
    def __init__(self) -> None:
        self._initialized = False
        self._status: Optional[str] = None
        self.n_vars: int = 0
        self.clauses: List[List[int]] = []
        self._original_clause_count: int = 0
        self._aux_var_count: int = 0
        self.watchlist: Dict[int, List[int]] = {}
        self.assign: List[int] = []
        self.decision_level: List[int] = []
        self.reason: List[int] = []
        self.trail: List[int] = []
        self.trail_lim: List[int] = []
        self.polarity_hint: List[int] = []
        self.var_activity: List[float] = []
        self.clause_activity: List[float] = []
        self.unit_queue: List[int] = []
        self.limits = Limits(-1, -1)
        self.policies = EncodingPolicies()
        self.stats = Stats()
        self._wall_start_ms: int = 0

    def init(self, cnf_meta: CnfMeta, limits: Limits, policies: EncodingPolicies) -> Dict[str, Any]:
        if cnf_meta.n_vars < 0:
            return {"ok": False, "err": E_BAD_INPUT}
        if limits.conflict_budget < -1 or limits.time_ms < -1:
            return {"ok": False, "err": E_LIMITS}
        self.n_vars = cnf_meta.n_vars
        self.clauses = [list(c) for c in cnf_meta.clauses]
        self._original_clause_count = len(self.clauses)
        self.stats = Stats(n_vars_original=self.n_vars,
                           n_vars_aux=self._aux_var_count,
                           n_clauses_original=self._original_clause_count,
                           n_clauses_total=len(self.clauses))
        self._initialized = True
        self._wall_start_ms = self._now_ms()
        return {"ok": True}

    def run(self, conflict_budget: int = -1, time_ms: int = -1) -> Dict[str, Any]:
        if not self._initialized:
            return {"status": None, "err": E_STATE}
        # TODO: implement full CDCL loop
        return {"status": "INCOMPLETE"}

    def add_learnt(self, clause: List[int]) -> Dict[str, Any]:
        if not clause:
            return {"ok": False, "err": E_BAD_INPUT}
        cid = len(self.clauses)
        self.clauses.append(list(clause))
        self.stats.n_clauses_learnt += 1
        self.stats.n_clauses_total = self._original_clause_count + self.stats.n_clauses_learnt
        return {"ok": True, "clause_id": cid}

    def snapshot(self) -> Dict[str, Any]:
        now_ms = self._now_ms()
        elapsed = now_ms - self._wall_start_ms
        if elapsed > self.stats.time_ms:
            self.stats.time_ms = elapsed
        return self.stats.__dict__

    def reset_stats(self) -> Dict[str, Any]:
        self.stats = Stats(n_vars_original=self.stats.n_vars_original,
                           n_vars_aux=self.stats.n_vars_aux,
                           n_clauses_original=self.stats.n_clauses_original,
                           n_clauses_learnt=self.stats.n_clauses_learnt,
                           n_clauses_total=self.stats.n_clauses_total)
        self._wall_start_ms = self._now_ms()
        return {"ok": True}

    @staticmethod
    def _now_ms() -> int:
        return int(time.time() * 1000)
"""

reporter_code = """# sat_core_report.py — Reporter & integration checks

from typing import Dict, Any, Tuple

E_REPORT = "E_REPORT"

REQUIRED_FIELDS = [
    "status",
    "n_conflicts","n_propagations","n_decisions","n_restarts","learnt_count",
    "avg_lbd","max_dl","trail_len_max",
    "time_ms",
    "limits_conflict_budget","limits_time_ms",
    "n_vars_original","n_vars_aux",
    "n_clauses_original","n_clauses_learnt","n_clauses_total",
    "encoding_policy_atmost1","encoding_policy_cardinality","restart_policy",
]

def validate_snapshot(prev: Dict[str, Any], cur: Dict[str, Any]) -> Tuple[bool, Dict[str, Any]]:
    missing = [k for k in REQUIRED_FIELDS if k not in cur]
    if missing:
        return False, {"err": E_REPORT, "why": "missing_fields", "fields": missing}
    if cur["n_clauses_total"] != cur["n_clauses_original"] + cur["n_clauses_learnt"]:
        return False, {"err": E_REPORT, "why": "accounting"}
    if prev:
        for k in ["n_conflicts","n_propagations","n_decisions","n_restarts","learnt_count","time_ms"]:
            if cur[k] < prev[k]:
                return False, {"err": E_REPORT, "why": "monotonic", "field": k}
    return True, {"ok": True}

def format_report(cur: Dict[str, Any]) -> Dict[str, Any]:
    denom = max(1, cur["time_ms"])
    conflicts_per_sec = cur["n_conflicts"] * 1000.0 / denom
    out = dict(cur)
    out["conflicts_per_sec"] = conflicts_per_sec
    return out
"""

with open("/mnt/data/sat_full.py", "w") as f:
    f.write(solver_code)

with open("/mnt/data/sat_core_report.py", "w") as f:
    f.write(reporter_code)

"/mnt/data files created"

